insert into public.site_settings (key, value) values ('general', '{"name":"Sarah Jaballah","email":"sarahjaballh@gmail.com","phone":"+216 23 340 362","whatsapp":"https://wa.me/21623340362","instagram":"https://www.instagram.com/sarah.jaballh/","qrUrl":"","qrLabel":{"en":"Scan to Explore My Portfolio","fr":"Scannez pour découvrir mon portfolio","ar":"امسح الرمز لاكتشاف أعمالي","es":"Escanea para descubrir mi portafolio"},"siteUrl":"https://portefilosarhaproject.netlify.app"}'::jsonb) on conflict do nothing;
insert into public.site_settings (key, value) values ('translations', '{}'::jsonb) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('hero', '{"kicker":{"en":"Cabin Crew · Customer Service · Guest Experience · Dance & Fitness","fr":"Personnel navigant · Service client · Expérience client · Danse & fitness","ar":"طاقم الضيافة الجوية · خدمة العملاء · تجربة الضيوف · الرقص واللياقة","es":"Tripulante de cabina · Atención al cliente · Experiencia del huésped · Danza y fitness"},"headline":{"en":"Creating Memorable Experiences Through Professionalism, Passion & Energy.","fr":"Créer des expériences mémorables avec professionnalisme, passion et énergie.","ar":"أصنع تجارب لا تُنسى بالاحترافية والشغف والطاقة.","es":"Creo experiencias memorables con profesionalidad, pasión y energía."},"intro":{"en":"Six years of welcoming people — from luxury hotel stages in Turkey to front desks and dance studios in Tunisia. Calm, punctual and multilingual, I am ready to take guest care to the skies.","fr":"Six ans à accueillir les gens, des scènes d’hôtels de luxe en Turquie aux accueils et studios de danse en Tunisie. Calme, ponctuelle et multilingue, je suis prête à porter le service client jusque dans les airs.","ar":"ست سنوات في استقبال الناس، من مسارح الفنادق الفاخرة في تركيا إلى مكاتب الاستقبال واستوديوهات الرقص في تونس. هادئة ومنضبطة في المواعيد ومتعددة اللغات، وجاهزة لأحمل رعاية الضيوف إلى السماء.","es":"Seis años recibiendo a personas: de los escenarios de hoteles de lujo en Turquía a recepciones y estudios de danza en Túnez. Serena, puntual y multilingüe, lista para llevar la atención al huésped a las alturas."}}'::jsonb, 0) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('about', '{"title":{"en":"Poise on stage. Care at every touchpoint.","fr":"De l’aisance sur scène. De l’attention à chaque instant.","ar":"حضور على المسرح، وعناية في كل لحظة.","es":"Aplomo en el escenario. Cuidado en cada detalle."},"body":{"en":"6+ years of public-facing experience in international hospitality, front-desk administration and fitness instruction. Performing for international guests in luxury hotels in Turkey built my presentation, punctuality, teamwork, multicultural communication and calm under pressure.","fr":"Plus de 6 ans d’expérience au contact du public dans l’hôtellerie internationale, l’administration d’accueil et l’enseignement du fitness. Me produire devant une clientèle internationale dans des hôtels de luxe en Turquie a forgé ma présentation, ma ponctualité, mon esprit d’équipe, ma communication interculturelle et mon calme sous pression.","ar":"أكثر من 6 سنوات من الخبرة في التعامل مع الجمهور في مجال الضيافة الدولية والإدارة والاستقبال وتدريب اللياقة البدنية. صقلت عروضي أمام ضيوف دوليين في فنادق فاخرة بتركيا حسن المظهر والالتزام بالمواعيد والعمل الجماعي والتواصل بين الثقافات والهدوء تحت الضغط.","es":"Más de 6 años de experiencia de cara al público en hostelería internacional, administración de recepción e instrucción de fitness. Actuar para huéspedes internacionales en hoteles de lujo en Turquía forjó mi presencia, puntualidad, trabajo en equipo, comunicación multicultural y calma bajo presión."},"location":{"en":"Tunisia","fr":"Tunisie","ar":"تونس","es":"Túnez"},"nationality":{"en":"Tunisian","fr":"Tunisienne","ar":"تونسية","es":"Tunecina"},"relocation":{"en":"Open to relocation","fr":"Mobilité internationale","ar":"مستعدة للانتقال","es":"Disponible para reubicarme"},"stats":[{"value":6,"suffix":"+","label":{"en":"Years customer-facing","fr":"Ans au contact du public","ar":"سنوات في خدمة العملاء","es":"Años de cara al público"}},{"value":4,"suffix":"","label":{"en":"Languages","fr":"Langues","ar":"لغات","es":"Idiomas"}},{"value":2,"suffix":"","label":{"en":"Countries","fr":"Pays","ar":"بلدان","es":"Países"}}]}'::jsonb, 1) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('dance', '{"intro":{"en":"Real moments from my classes: Zumba, dance and fitness sessions where every age and level finds its rhythm.","fr":"De vrais moments de mes cours : Zumba, danse et fitness, où chaque âge et chaque niveau trouve son rythme.","ar":"لحظات حقيقية من حصصي: زومبا ورقص ولياقة، حيث يجد كل عمر وكل مستوى إيقاعه.","es":"Momentos reales de mis clases: Zumba, danza y fitness, donde cada edad y nivel encuentra su ritmo."}}'::jsonb, 2) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('contact', '{"intro":{"en":"Recruiting cabin crew or building a guest-experience team? Let’s talk.","fr":"Vous recrutez du personnel navigant ou une équipe d’accueil ? Parlons-en.","ar":"هل توظفون طاقم ضيافة أو تبنون فريقًا لتجربة الضيوف؟ لنتحدث.","es":"¿Buscas tripulantes de cabina o un equipo de atención al huésped? Hablemos."}}'::jsonb, 3) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('ledex', '2024 – 2026', 1, true, '{"en":"Dance Performer & Guest Experience","fr":"Danseuse & expérience client","ar":"راقصة استعراضية وتجربة الضيوف","es":"Bailarina y experiencia del huésped"}'::jsonb, '{"en":"LEDEX Event Company","fr":"LEDEX Event Company","ar":"شركة LEDEX للفعاليات","es":"LEDEX Event Company"}'::jsonb, '{"en":"Turkey","fr":"Turquie","ar":"تركيا","es":"Turquía"}'::jsonb, '{"en":["Performed shows in luxury hotels and events for international guests","Interacted with guests before and after shows","Worked within multinational teams on synchronized performances","Adapted quickly to new venues and last-minute changes","Upheld strict grooming, uniform and conduct standards"],"fr":["Spectacles dans des hôtels de luxe et des événements pour une clientèle internationale","Échanges avec les clients avant et après les spectacles","Travail en équipes multinationales sur des chorégraphies synchronisées","Adaptation rapide à de nouveaux lieux et aux changements de dernière minute","Respect rigoureux des standards de présentation, d’uniforme et de conduite"],"ar":["تقديم عروض في فنادق فاخرة وفعاليات لضيوف دوليين","التواصل مع الضيوف قبل العروض وبعدها","العمل ضمن فرق متعددة الجنسيات في عروض متناسقة","التكيّف السريع مع أماكن جديدة وتغييرات اللحظة الأخيرة","الالتزام الصارم بمعايير المظهر والزي والسلوك"],"es":["Espectáculos en hoteles de lujo y eventos para huéspedes internacionales","Interacción con los huéspedes antes y después de cada show","Trabajo en equipos multinacionales con coreografías sincronizadas","Adaptación rápida a nuevos espacios y cambios de última hora","Cumplimiento estricto de normas de imagen, uniforme y conducta"]}'::jsonb) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('academy', '2020 – 2024', 2, true, '{"en":"Receptionist & Administrative Assistant","fr":"Réceptionniste & assistante administrative","ar":"موظفة استقبال ومساعدة إدارية","es":"Recepcionista y asistente administrativa"}'::jsonb, '{"en":"Academy of Arts & Sports","fr":"Académie des Arts & Sports","ar":"أكاديمية الفنون والرياضة","es":"Academia de Artes y Deportes"}'::jsonb, '{"en":"Tunisia","fr":"Tunisie","ar":"تونس","es":"Túnez"}'::jsonb, '{"en":["Welcomed visitors and handled calls, emails and inquiries","Managed registrations, payment follow-ups and member records","Organised class schedules","Resolved complaints with courtesy","Coordinated parents, instructors and management","Supported events and guest reception"],"fr":["Accueil des visiteurs, gestion des appels, e-mails et demandes","Inscriptions, suivi des paiements et dossiers des adhérents","Organisation des plannings de cours","Traitement courtois des réclamations","Coordination entre parents, professeurs et direction","Soutien aux événements et à l’accueil des invités"],"ar":["استقبال الزوار والرد على المكالمات والبريد الإلكتروني والاستفسارات","إدارة التسجيلات ومتابعة المدفوعات وسجلات الأعضاء","تنظيم جداول الحصص","معالجة الشكاوى بلباقة","التنسيق بين الأولياء والمدربين والإدارة","دعم الفعاليات واستقبال الضيوف"],"es":["Recepción de visitantes, llamadas, correos y consultas","Inscripciones, seguimiento de pagos y registros de socios","Organización de horarios de clases","Resolución cortés de reclamaciones","Coordinación entre familias, profesores y dirección","Apoyo en eventos y recepción de invitados"]}'::jsonb) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('instructor', '2019 – 2024', 3, true, '{"en":"Dance & Fitness Instructor","fr":"Professeure de danse & fitness","ar":"مدربة رقص ولياقة بدنية","es":"Instructora de danza y fitness"}'::jsonb, '{"en":"Various Schools & Studios","fr":"Écoles & studios divers","ar":"مدارس واستوديوهات مختلفة","es":"Diversas escuelas y estudios"}'::jsonb, '{"en":"Tunisia","fr":"Tunisie","ar":"تونس","es":"Túnez"}'::jsonb, '{"en":["Led dance, Zumba and fitness classes","Supervised children, teens and adults","Kept every participant safe and well","Adapted sessions to all ages and abilities","Created inclusive, motivating sessions"],"fr":["Animation de cours de danse, de Zumba et de fitness","Encadrement d’enfants, d’adolescents et d’adultes","Sécurité et bien-être de chaque participant","Adaptation des séances à tous les âges et niveaux","Des séances inclusives et motivantes"],"ar":["تقديم حصص الرقص والزومبا واللياقة البدنية","الإشراف على الأطفال والمراهقين والبالغين","الحرص على سلامة كل مشارك وراحته","تكييف الحصص مع جميع الأعمار والقدرات","خلق أجواء محفّزة تشمل الجميع"],"es":["Clases de danza, Zumba y fitness","Supervisión de niños, adolescentes y adultos","Seguridad y bienestar de cada participante","Sesiones adaptadas a todas las edades y niveles","Clases inclusivas y motivadoras"]}'::jsonb) on conflict do nothing;
